import type {DurableStepEvent} from '../../types.js'

type PendingRetry = {index: number; event: DurableStepEvent; delayMs: number}

export function createStepHistory(): {
  startRun: () => void
  nextStep: () => {index: number; saved: DurableStepEvent | undefined}
  recordSuccess: (index: number, event: DurableStepEvent) => void
  recordFailure: (
    index: number,
    failure: {event: DurableStepEvent; error: unknown; delayMs: number},
  ) => boolean
  getPending: () => PendingRetry | null
  settle: (pending: PendingRetry) => void
}
